using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Clinical;

namespace FamilyVeda.Domain.Portal;

public enum PortalRequestStatus { Pending, Accepted, Declined, Cancelled, Expired }

public enum AppointmentStatus { Requested, Confirmed, Completed, Cancelled, NoShow }

public sealed class FamilyJoinRequest : Entity
{
    public Guid FamilyId { get; set; }
    public Family? Family { get; set; }
    public Guid RequestingUserId { get; set; }
    public UserAccount? RequestingUser { get; set; }
    public required string RelationshipType { get; set; }
    public string? Message { get; set; }
    public PortalRequestStatus Status { get; set; } = PortalRequestStatus.Pending;
    public DateTimeOffset? RespondedAt { get; set; }
    public Guid? RespondedByUserId { get; set; }
}

public sealed class FamilyDoctorRequest : Entity
{
    public Guid FamilyId { get; set; }
    public Family? Family { get; set; }
    public Guid DoctorId { get; set; }
    public Doctor? Doctor { get; set; }
    public Guid RequestedByUserId { get; set; }
    public string? Message { get; set; }
    public PortalRequestStatus Status { get; set; } = PortalRequestStatus.Pending;
    public DateTimeOffset? RespondedAt { get; set; }
}

public sealed class Appointment : Entity
{
    public Guid MemberId { get; set; }
    public Member? Member { get; set; }
    public Guid DoctorId { get; set; }
    public Doctor? Doctor { get; set; }
    public Guid BookedByUserId { get; set; }
    public DateTimeOffset StartsAt { get; set; }
    public int DurationMinutes { get; set; } = 30;
    public required string Reason { get; set; }
    public AppointmentStatus Status { get; set; } = AppointmentStatus.Requested;
    public string? DoctorNote { get; set; }
    public DateTimeOffset? RescheduledFromStartsAt { get; set; }
}

public sealed class PortalNotification : Entity
{
    public Guid UserId { get; set; }
    public UserAccount? User { get; set; }
    public required string Type { get; set; }
    public required string Title { get; set; }
    public required string Body { get; set; }
    public string? LinkPath { get; set; }
    public DateTimeOffset? ReadAt { get; set; }
}
